INSERT INTO `instagram_posts` (`id`, `title`, `instagram_url`, `description`, `status`, `sort_order`, `created_at`) VALUES
(1, 'Magang ke jepang', 'https://www.instagram.com/reel/DZE77u4oNN_/?utm_source=ig_web_button_share_sheet', 'Fii Amanillah Surya Difraja @_.prajaa \r\n(Alumni SMK INFOKOM Angkatan XVII)\r\nSelamat sampai Negeri Sakura (Tokyo) & betah-betah disana..\r\nTerima Kasih telah membanggakan almamatermu nak! 💙\r\nTerbang tinggi menembus batas untuk mengejar cita-cita dan masa depanmu yang manis~\r\nWe Love You, Surya Difraja 💙', 'published', 1, '2026-09-28 05:23:42'),
(2, 'UPACARA BENDERA 17 AGUSTUS', 'https://www.instagram.com/reel/DcISDWMoMtp/?utm_source=ig_web_button_share_sheet', 'Anak anak upacara hari minggu walaupun tanggal merah', 'published', 2, '2026-09-28 14:20:31'),
(3, 'PPDB', 'https://www.instagram.com/reel/DVNsjvFklWf/?utm_source=ig_web_button_share_sheet', 'Hallo Sahabat INFOKOM,\r\n\r\n“Bingung Mau Lanjut Kemana???”\r\n\r\nke SMK INFOKOM Kota Bogor aja!\r\n\r\nSekolah kami memiliki 4 Kompetensi Keahlian, yaitu:\r\n- Teknik Komputer dan Jaringan (TKJ)\r\n- Rekayasa Perangkat Lunak (RPL)\r\n- Desain Komunikasi Visual (DKV)\r\n- Produksi dan Siaran Program Televisi (PSPT/Broadcasting)\r\n\r\nSo, untuk kalian adik-adik kelas IX yg mau melanjutkan ke jenjang berikutnya dan ingin banyak mendapat ilmu dan skill sesuai dgn bidang diatas, Yukkk bergabung bersama kami!\r\nInsyaAllah, gaakan nyesel loooh… 🤗\r\n\r\nUntuk informasi PPDB lebih lanjut, bisa mengakses website kami di: www.smkinfokom-bogor.sch.id atau bisa klink link di Biografi kami.\r\n\r\nSee U on Top, guys~\r\n\r\n#spmbjabar \r\n#spmb2026\r\n#smk \r\n#spmbjabar2026', 'published', 3, '2026-09-28 14:41:15');

